import {createAppDataClient} from '../../packages/app-data-client/src/index.ts';
import type {RecordRow, DocumentWriteOptions} from '../../packages/app-data-client/src/index.ts';

export interface WorkOrder {title: string; priority: number; done: boolean}

/** Plug authorize into Scaffold's existing requireAuth + business permission checks. */
export function workOrdersService(
  data: ReturnType<typeof createAppDataClient>,
  authorize: (action: 'read' | 'create' | 'complete') => Promise<void>,
) {
  return {
    async list(page = 1, done?: boolean) {
      await authorize('read');
      const orders = await data.collection<WorkOrder>('orders');
      const pageResult = await orders.aggregate<WorkOrder & {_id:string;_meta:Omit<RecordRow<WorkOrder>,'id'|'data'>}>([
        {$match: done === undefined ? {} : {'done': done}},
        {$sort: [['priority',-1],['_id',1]]},
      ], {page: {mode: 'offset', page, size: 20}});
      return {...pageResult,items:pageResult.items.map(({_id,_meta,...value})=>({..._meta,id:_id,data:value as WorkOrder}))};
    },
    async create(input: Pick<WorkOrder, 'title' | 'priority'>, write: DocumentWriteOptions & {id?: string}) {
      await authorize('create');
      if (!input.title.trim() || !Number.isInteger(input.priority) || input.priority < 0) throw new Error('Invalid work order');
      const orders = await data.collection<WorkOrder>('orders');
      const {id, ...options} = write;
      return orders.insertOne({title: input.title.trim(), priority: input.priority, done: false}, {...options,...(id?{id}:{})});
    },
    async complete(record: Pick<RecordRow<WorkOrder>, 'id' | 'revision'>, write: DocumentWriteOptions) {
      await authorize('complete');
      const orders = await data.collection<WorkOrder>('orders');
      // Send the revision the user viewed. A stale screen returns VERSION_CONFLICT.
      return orders.updateOne({_id:record.id},{$set:{done:true}},{...write,expectedRevision:record.revision});
    },
  };
}

// Current data/3 HTTP acceptance. Only creates uniquely named fixtures and keys;
// never resets a database. Supply the explicitly selected instance and password.
import assert from 'node:assert/strict';
import {randomUUID} from 'node:crypto';
import {setTimeout as delay} from 'node:timers/promises';

const base = process.env.UNS_SMOKE_BASE;
assert.ok(base && process.env.UNS_SMOKE_PASSWORD, 'UNS_SMOKE_BASE and UNS_SMOKE_PASSWORD required');
const prefix = `data3-${randomUUID().slice(0, 8)}`;
const collectionId = `${prefix}-records`, sampleCollectionId = `${prefix}-samples`;
const createdKeys = [], appKeys = [], cases = [];
let token, manager, sequence = 0;
async function request(path, body, key = manager, method = 'POST') {
  const response = await fetch(base + path, {method, signal: AbortSignal.timeout(30000), headers: {
    'Content-Type': 'application/json', ...(key ? {'X-API-Key': key} : token ? {Authorization: `Bearer ${token}`} : {}),
  }, ...(body === undefined ? {} : {body: JSON.stringify(body)})});
  const text = await response.text();
  let value; try { value = JSON.parse(text); } catch { throw Error(`${path}: HTTP ${response.status}, non-JSON response`); }
  return {status: response.status, value};
}
async function ok(path, body, key = manager, method) {
  const r = await request(path, body, key, method);
  assert.equal(r.status, 200, `${path}: ${JSON.stringify(r.value.error || r.value.msg)}`);
  assert.equal(r.value.code, 200); return r.value.data;
}
const api = (suffix, body, key) => ok(`/openapi/v2/uns/${suffix}`, body, key);
const scoped = (id, action) => `collections/${encodeURIComponent(id)}/${action}`;
const record = (action, body = {}, key) => api(scoped(collectionId, `records${action ? ':' + action : ''}`), body, key);
const sample = (action, body = {}, key) => api(scoped(sampleCollectionId, `samples:${action}`), body, key);
const write = body => ({dryRun: false, idempotencyKey: `${prefix}-${++sequence}`, ...body});
const get = async id => (await record('find', {filter: {_id: id}})).items[0];
function page(value) {
  assert.ok(Array.isArray(value.items));
  assert.deepEqual(Object.keys(value.pageInfo).sort(), ['hasMore', 'mode', 'nextCursor', 'nextPage', 'snapshotScope']);
  assert.equal(value.pageInfo.snapshotScope, 'thisRequestOnly');
  assert.equal(typeof value.pageInfo.hasMore, 'boolean');
  assert.ok(['cursor', 'offset'].includes(value.pageInfo.mode));
}
function document(value, id = collectionId) {
  assert.ok(value && typeof value.id === 'string'); assert.equal(value.collectionId, id);
  assert.equal(typeof value.data, 'object'); assert.ok(Number.isInteger(value.revision));
  assert.ok(Number.isInteger(value.createdAt) && Number.isInteger(value.updatedAt));
  assert.ok(Object.hasOwn(value, 'sourceId') && Object.hasOwn(value, 'sourceTime'));
  assert.ok(!Object.hasOwn(value, '_meta') && !Object.hasOwn(value, '_id'));
  if (value.lock) assert.ok(!Object.hasOwn(value.lock, 'token') && !Object.hasOwn(value.lock, 'principal'));
}
async function denied(suffix, body, key, status = 403) {
  const r = await request(`/openapi/v2/uns/${suffix}`, body, key);
  assert.equal(r.status, status, `${suffix}: ${JSON.stringify(r.value.error)}`); assert.ok(r.value.error?.code);
}
async function personal(scopes, name) {
  const value = await ok('/api/core/common/api-keys', {name: `${prefix}-${name}`, permission: 'full_access', keyType: 'personal', resourceKeys: scopes}, null);
  createdKeys.push(value.id); return value.apiKey;
}
async function complete(outcome) {
  if (outcome.status !== 'accepted') return outcome;
  for (let i = 0; i < 120; i++) {
    const job = (await api('jobs/query', {queries: [{queryId: 'job', jobIds: [outcome.jobId]}]})).results[0].list[0];
    if (job.status === 'succeeded') return job.result;
    assert.notEqual(job.status, 'failed', JSON.stringify(job.error)); await delay(250);
  }
  assert.fail('async job timed out');
}
try {
  token = (await ok('/api/core/auth/login', {username: process.env.UNS_SMOKE_USERNAME || 'tier0', password: process.env.UNS_SMOKE_PASSWORD}, null)).token;
  manager = await personal(['uns.read', 'uns.write', 'uns.manage', 'uns.delete', 'uns.app.read', 'uns.app.manage', 'uns.app.credentials'], 'manager');
  const readOnly = await personal(['uns.read'], 'read');
  const catalog = await api('catalog/get', {});
  for (const suffix of ['/uns/records/query', '/uns/samples/query', '/uns/records/create', '/uns/records/transaction', '/uns/latest']) {
    assert.ok(!catalog.operations.some(o => o.suffix === suffix), `retired catalog entry ${suffix}`);
  }
  for (const action of ['records:find', 'records:aggregate', 'records:restore', 'records:lock', 'samples:find', 'samples:aggregate', 'samples:latest', 'samples:delete']) {
    assert.ok(catalog.operations.some(o => o.suffix.endsWith('/' + action)), `missing operation ${action}`);
  }
  const recordSchema = {type: 'object', properties: {name: {type: 'string'}, value: {type: 'number'}, note: {type: 'string'}}, required: ['name', 'value'], additionalProperties: false};
  for (const id of [collectionId, sampleCollectionId]) await complete(await api('collections/create', write({id, name: id, recordSchema,
    ...(id === sampleCollectionId ? {sampleSchema: {type: 'object', properties: {value: {type: 'number'}}, required: ['value'], additionalProperties: false}} : {})})));
  const preview = await record('', write({id: 'dry', data: {name: 'Dry', value: 0}, dryRun: true}));
  assert.equal(preview.status, 'validated'); assert.equal(await get('dry'), undefined);
  const inserted = await record('', write({id: 'one', data: {name: 'One', value: 1}}));
  assert.equal(inserted.insertedId, 'one'); assert.equal(inserted.status, 'committed'); document(await get('one'));
  const manyBody = write({ordered: false, operations: [{id: 'two', data: {name: 'Two', value: 2}}, {id: 'invalid', data: {name: 'Invalid', value: 'bad'}}, {id: 'three', data: {name: 'Three', value: 3}}].map(insertOne => ({insertOne}))});
  const many = await record('bulkWrite', manyBody);
  assert.deepEqual(many.insertedIds, {'0': 'two', '2': 'three'}); assert.equal(many.insertedCount, 2); assert.equal(many.writeErrors[0].index, 1);
  assert.equal((await record('bulkWrite', manyBody)).replayed, true);
  const filter = {$or: [{value: {$gte: 1}}, {_id: 'missing'}]};
  const first = await record('find', {filter, sort: [['_id', 1]], projection: {value: 1}, limit: 1});
  page(first); document(first.items[0]); assert.deepEqual(Object.keys(first.items[0].data), ['value']); assert.equal(first.pageInfo.hasMore, true);
  const second = await record('find', {filter, sort: [['_id', 1]], projection: {value: 1}, limit: 1, cursor: first.pageInfo.nextCursor});
  assert.notEqual(second.items[0].id, first.items[0].id);
  const findBody = {filter: {_id: 'one'}};
  const internal = await ok(`/api/core/v2/uns/${scoped(collectionId, 'records:find')}`, findBody, null);
  assert.deepEqual(internal, await record('find', findBody));
  assert.equal((await record('count')).count, 3);
  const distinctPipeline = [{$group: {_id: '$value'}}];
  const values = await record('aggregate', {pipeline: distinctPipeline, page: {mode: 'offset', page: 1, size: 1}});
  assert.equal(values.items.length, 1); assert.equal(values.pageInfo.hasMore, true);
  const moreValues = await record('aggregate', {pipeline: distinctPipeline, page: {mode: 'offset', page: values.pageInfo.nextPage, size: 1}});
  assert.notDeepEqual(moreValues.items, values.items);
  const aggregate = await record('aggregate', {pipeline: [{$match: {value: {$gte: 1}}}, {$group: {_id: null, total: {$sum: '$value'}}}]});
  page(aggregate); assert.equal(aggregate.items[0].total, 6); assert.ok(!Object.hasOwn(aggregate.items[0], 'data'));
  cases.push('canonical Record, partial batch indices/replay, cursor/projection, count/distinct and flat pipeline');

  const updated = await record('updateOne', write({filter: {_id: 'one'}, update: {$inc: {value: 1}}, returnDocument: 'after'}));
  document(updated.value); assert.equal(updated.value.data.value, 2);
  const replaced = await record('replaceOne', write({filter: {_id: 'two'}, replacement: {name: 'Replaced', value: 20}, returnDocument: 'before'}));
  document(replaced.value); assert.equal(replaced.value.data.value, 2);
  const upsert = await record('updateOne', write({filter: {_id: 'upsert'}, update: {$set: {name: 'Upsert', value: 4}}, upsert: true, returnDocument: 'before'}));
  assert.equal(upsert.value, null); assert.equal(upsert.upsertedId, 'upsert');
  const bulk = await record('bulkWrite', write({ordered: false, operations: [
    {insertOne: {id: 'bulk-0', data: {name: 'Bulk', value: 5}}},
    {insertOne: {id: 'bulk-invalid', data: {name: 'Invalid', value: 'bad'}}},
    {updateOne: {filter: {_id: 'bulk-2'}, update: {$set: {name: 'Upsert bulk', value: 6}}, upsert: true}},
  ]}));
  assert.deepEqual(bulk.insertedIds, {'0': 'bulk-0'}); assert.deepEqual(bulk.upsertedIds, {'2': 'bulk-2'}); assert.equal(bulk.writeErrors[0].index, 1);
  const removed = await record('deleteOne', write({filter: {_id: 'one'}, returnDocument: 'before'})); document(removed.value); assert.equal(await get('one'), undefined);
  await record('deleteOne', write({filter: {_id: 'two'}}));
  const restored = await record('restore', write({ids: ['one', 'two']})); assert.equal(restored.restoredCount, 2); assert.deepEqual([...restored.restoredIds].sort(), ['one', 'two']);
  document(await get('one')); document(await get('two'));
  cases.push('canonical write snapshots, upsert, bulk original indices and multi-ID restore');

  const lease = (await record('lock', {ids: ['one'], ttlMs: 30000, label: prefix})).locks[0];
  assert.equal(lease.id, 'one'); assert.equal(typeof lease.token, 'string'); document(lease.record);
  assert.ok(lease.record.lock); assert.equal((await record('renew', {locks: [{id: lease.id, token: lease.token}], ttlMs: 30000})).locks[0].id, 'one');
  await denied(scoped(collectionId, 'records:updateOne'), write({filter: {_id: 'one'}, update: {$inc: {value: 1}}}), manager, 409);
  const locked = await record('updateOne', write({filter: {_id: 'one'}, update: {$inc: {value: 1}}, lockToken: lease.token, returnDocument: 'after'}));
  document(locked.value); assert.equal((await record('unlock', {locks: [{id: lease.id, token: lease.token}]})).unlockedCount, 1);
  const txnBody = write({items: [{opId: 'read', action: 'record.read', collectionId, id: 'one'}, {opId: 'query', action: 'record.query', collectionId, query: {filter: {_id: 'one'}, limit: 1}}]});
  const txn = await api('records:transact', txnBody); document(txn.results[0].document); document(txn.results[1].query.records[0]);
  assert.deepEqual(txn.results[0].data, txn.results[0].document.data); assert.equal((await api('records:transact', txnBody)).replayed, true);
  await denied(scoped(collectionId, 'records'), write({data: {name: 'Denied', value: 0}}), readOnly);
  await denied('records:transact', write({items: [{action: 'record.create', collectionId, id: 'denied', data: {name: 'Denied', value: 0}}]}), readOnly);
  cases.push('lease Record/renew/unlock, token enforcement, canonical transaction documents and write denial');

  const appId = `${prefix}-app`;
  await api('apps/create', write({id: appId, name: appId}));
  await api('apps/grants/update', write({id: appId, expectedRevision: 1, collections: [{alias: 'records', collectionId, permissions: ['record:read']}]}));
  const app = await api('apps/keys/create', {appId, name: prefix}); appKeys.push({appId, keyId: app.keyId});
  page(await record('find', {}, app.apiKey));
  await denied(scoped(sampleCollectionId, 'records:find'), {}, app.apiKey);
  await denied(scoped(collectionId, 'records:lock'), {ids: ['one']}, app.apiKey);
  await denied(scoped(collectionId, 'records:unlock'), {ids: ['one'], force: true}, app.apiKey);
  cases.push('App per-Collection read isolation and lease/force-unlock denial');

  await api(scoped(sampleCollectionId, 'records:bulkWrite'), write({operations: ['s1', 's2'].map(id => ({insertOne: {id, data: {name: id, value: 0}}})), atomic: true}));
  const from = Date.now() - 10000, to = from + 20000;
  for (const id of ['s1', 's2']) await api(scoped(sampleCollectionId, `records/${id}/samples`), write({items: [
    {id: `${id}-zero`, time: from + 1000, data: {value: 0}}, {id: `${id}-last`, time: from + 2000, data: {value: id === 's1' ? 10 : 11}},
  ]}));
  const scope = {recordIds: ['s1', 's2'], from, to};
  const found = await sample('find', {...scope, filter: {$or: [{value: {$gt: 0}}, {value: 0}]}, limit: 10}); page(found); assert.equal(found.items.length, 4);
  for (const item of found.items) {
    assert.equal(item.collectionId, sampleCollectionId); assert.ok(Number.isInteger(item.time) && Number.isInteger(item.receivedAt));
    assert.ok(Object.hasOwn(item, 'sourceId') && Object.hasOwn(item, 'quality')); assert.equal(typeof item.data.value, 'number');
  }
  const latest = await sample('latest', {recordIds: ['s1', 's2']}); assert.equal(latest.series.length, 2);
  for (const series of latest.series) assert.deepEqual(series.sample, found.items.find(row => row.id === `${series.recordId}-last`));
  const grouped = await sample('aggregate', {...scope, pipeline: [{$group: {_id: '$_meta.recordId', total: {$sum: '$value'}}}]}); page(grouped);
  assert.equal(grouped.items.length, 2); assert.deepEqual(grouped.items.map(row => row.total).sort((a, b) => a - b), [10, 11]);
  const narrow = await sample('find', {recordIds: ['s1'], from: from + 2000, to: from + 2001, filter: {$or: [{value: {$gt: 1000}}, {value: {$gte: 0}}]}});
  assert.equal(narrow.items.length, 1); assert.equal(narrow.items[0].recordId, 's1');
  await denied(scoped(sampleCollectionId, 'samples:find'), {from, to, recordIds: []}, manager, 422);
  await denied(scoped(sampleCollectionId, 'samples:latest'), {}, manager, 422);
  const previewDelete = await sample('delete', {...scope, dryRun: true}); assert.equal(previewDelete.dryRun, true); assert.equal(previewDelete.deletedCount, 4);
  assert.equal((await sample('find', scope)).items.length, 4);
  const deleted = await sample('delete', {...scope, dryRun: false}); assert.equal(deleted.deletedCount, 4); assert.equal((await sample('find', scope)).items.length, 0);
  assert.equal((await api(scoped(sampleCollectionId, 'records:count'), {})).count, 2);
  cases.push('multi-record Sample complex find/aggregate/latest, mandatory scope and explicit range deletion');
  console.log(JSON.stringify({status: 'passed', prefix, cases, fixtures: [collectionId, sampleCollectionId], cleanup: 'temporary keys revoked; namespaced fixture data retained for inspection'}, null, 2));
} finally {
  for (const key of appKeys) await api('apps/keys/revoke', key);
  if (token) for (const id of createdKeys) await request(`/api/core/common/api-keys/${id}`, undefined, null, 'DELETE');
}

package repo

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"backend/internal/unsref"
	"github.com/jackc/pgx/v5/pgconn"
	"gorm.io/gorm"
)

// 新版 UNS 元数据与业务数据统一使用 UNS 连接；不复用旧 Topic 物理表。
var ErrMountedReadOnly = errors.New("mounted UNS resources are read-only")

type UnsMeta struct {
	OriginNodeID string          `gorm:"column:origin_node_id" json:"originNodeId,omitempty"`
	ID           string          `gorm:"column:id;primaryKey" json:"id"`
	MountID      *string         `gorm:"column:mount_id" json:"mountId"`
	Kind         string          `gorm:"-" json:"kind"`
	StorageKind  string          `gorm:"column:kind;primaryKey" json:"-"`
	Data         json.RawMessage `gorm:"column:data;type:jsonb" json:"data"`
	Revision     int64           `gorm:"column:revision" json:"revision"`
	CreatedAt    int64           `gorm:"column:created_at;autoCreateTime:milli" json:"createdAt"`
	UpdatedAt    int64           `gorm:"column:updated_at;autoUpdateTime:milli" json:"updatedAt"`
	DeletedAt    int64           `gorm:"column:deleted_at" json:"deletedAt"`
}

func (UnsMeta) TableName() string { return "public.uns_meta" }

// Legacy folder DTOs map to directory storage; Topic has its own storage kind.
func (m *UnsMeta) BeforeCreate(*gorm.DB) error {
	m.StorageKind = m.Kind
	if m.Kind == "folder" {
		m.StorageKind = "directory"
	}
	return nil
}
func (m *UnsMeta) AfterFind(*gorm.DB) error {
	m.Kind = m.StorageKind
	if m.Kind == "directory" {
		m.Kind = "folder"
	}
	return nil
}

type UnsRecord struct {
	// Write acknowledgement only; never persisted or exposed as a stored record field.
	DeliveryState string          `gorm:"-" json:"-"`
	DeletedAt     gorm.DeletedAt  `gorm:"column:deleted_at;index" json:"-"`
	SourceTime    *time.Time      `gorm:"column:source_time" json:"sourceTime,omitempty"`
	LockTokenHash []byte          `gorm:"column:lock_token_hash" json:"-"`
	LockPrincipal string          `gorm:"column:lock_principal" json:"-"`
	LockLabel     string          `gorm:"column:lock_label" json:"-"`
	LockExpiresAt *time.Time      `gorm:"column:lock_expires_at" json:"-"`
	LockFence     int64           `gorm:"column:lock_fence" json:"-"`
	LockSince     *time.Time      `gorm:"column:lock_since" json:"-"`
	SourceID      *string         `gorm:"column:source_id" json:"sourceId,omitempty"`
	CollectionID  string          `gorm:"column:collection_id;primaryKey" json:"collectionId"`
	ID            string          `gorm:"column:id;primaryKey" json:"id"`
	Data          json.RawMessage `gorm:"column:data;type:jsonb" json:"data"`
