func sourceStreamPage(page, size int) (int, int) {
	if page < 1 {
		page = 1
	}
	if size < 1 {
		size = 50
	}
	if size > 200 {
		size = 200
	}
	return (page - 1) * size, size
}
func sourceKey(id int64) string { return strconv.FormatInt(id, 10) }
func metaQuery(db *gorm.DB, kind string) *gorm.DB {
	return db.Model(&UnsMeta{}).Where("kind = ?", kind)
}
func sourceRow(db *gorm.DB, id int64, lock string) (UnsMeta, sourceMetaData, error) {
	var row UnsMeta
	var data sourceMetaData
	q := metaQuery(db, "source").Where("id = ? AND deleted_at = 0", sourceKey(id))
	if lock != "" {
		q = q.Clauses(clause.Locking{Strength: lock})
	}
	if err := q.Take(&row).Error; err != nil {
		return row, data, err
	}
	err := json.Unmarshal(row.Data, &data)
	return row, data, err
}
func stateRow(db *gorm.DB, id int64, lock bool) (UnsMeta, sourceStateData, error) {
	var row UnsMeta
	var data sourceStateData
	q := metaQuery(db, "source_state").Where("id = ?", sourceKey(id))
	if lock {
		q = q.Clauses(clause.Locking{Strength: "UPDATE"})
	}
	if err := q.Take(&row).Error; err != nil {
		return row, data, err
	}
	err := json.Unmarshal(row.Data, &data)
	return row, data, err
}
func saveMetaData(db *gorm.DB, row *UnsMeta, data any) error {
	raw, err := json.Marshal(data)
	if err != nil {
		return err
	}
	row.Data = raw
	row.Revision++
	row.UpdatedAt = time.Now().UnixMilli()
	return db.Model(&UnsMeta{}).Where("kind = ? AND id = ?", row.Kind, row.ID).Updates(map[string]any{"data": raw, "revision": row.Revision, "updated_at": row.UpdatedAt, "deleted_at": row.DeletedAt}).Error
}
func projectSource(row UnsMeta, data sourceMetaData, state sourceStateData) (Source, error) {
	id, err := strconv.ParseInt(row.ID, 10, 64)
	return Source{ConnectionCheck: state.ConnectionCheck, DataCheck: state.DataCheck, ID: id, Name: data.Name, Protocol: data.Adapter, Document: string(data.Config.Connection), Revision: row.Revision, ConfigRevision: data.ConfigRevision, DesiredState: data.DesiredState, Health: state.Health, HealthMessage: state.HealthMessage, Resources: string(state.Resources), LastDataAt: state.LastDataAt, CheckedAt: state.CheckedAt, CreatedAt: row.CreatedAt, UpdatedAt: row.UpdatedAt, DeletedAt: row.DeletedAt}, err
}
func projectStream(sourceID int64, id string, c streamConfig) (Stream, error) {
	if c.Model == "script" || c.Model == "program" {
		sourceID = 0
	}
	n, err := strconv.ParseInt(id, 10, 64)
	return Stream{ID: n, SourceID: sourceID, Name: c.Name, Model: c.Model, Document: string(c.Document), Revision: c.Revision, ActiveVersion: c.ActiveVersion, PendingVersion: c.PendingVersion, DraftManifest: string(c.DraftManifest), Status: c.Status, CreatedAt: c.CreatedAt, UpdatedAt: c.UpdatedAt, DeletedAt: c.DeletedAt}, err
}
func (r *SourceStreamRepo) Source(ctx context.Context, id int64) (Source, error) {
	row, data, err := sourceRow(r.db.WithContext(ctx), id, "")
	if err != nil {
		return Source{}, err
	}
	_, state, err := stateRow(r.db.WithContext(ctx), id, false)
	if err != nil {
		return Source{}, err
	}
	return projectSource(row, data, state)
}
func (r *SourceStreamRepo) ListSources(ctx context.Context, f SourceFilter) ([]Source, int64, error) {
	q := metaQuery(r.db.WithContext(ctx), "source").Where("deleted_at=0")
	// This numeric-ID compatibility API projects the legacy connection format.
	// Versioned Sources contain reusable Stream bindings and string IDs; read them
	// through UNS v2 instead. Filter before count/pagination, never drop data or
	// infer the format from an ID prefix.
	q = q.Where("COALESCE(data->>'schemaVersion', '') <> '1'")
	if f.Search != "" {
		q = q.Where("data->>'name' ILIKE ?", "%"+f.Search+"%")
	}
	if f.Protocol != "" {
		q = q.Where("data->>'adapter' = ?", f.Protocol)
	}
	if f.DesiredState != "" {
		q = q.Where("COALESCE(NULLIF(data->>'desiredState', ''), 'enabled') = ?", f.DesiredState)
	}
	if f.Health != "" {
		q = q.Where("id IN (SELECT id FROM public.uns_meta WHERE kind='source_state' AND data->>'health' = ?)", f.Health)
	}
	var count int64
	if err := q.Count(&count).Error; err != nil {
		return nil, 0, err
	}
	offset, size := sourceStreamPage(f.Page, f.Size)
	var rows []UnsMeta
	if err := q.Order("created_at DESC,id DESC").Offset(offset).Limit(size).Find(&rows).Error; err != nil {
		return nil, 0, err
	}
	items := []Source{}
	for _, row := range rows {
		var d sourceMetaData
		if err := json.Unmarshal(row.Data, &d); err != nil {
			return nil, 0, err
		}
		id, err := strconv.ParseInt(row.ID, 10, 64)
		if err != nil {
			return nil, 0, err
		}
		_, state, err := stateRow(r.db.WithContext(ctx), id, false)
		if err != nil {
			return nil, 0, err
		}
		item, err := projectSource(row, d, state)
		if err != nil {
			return nil, 0, err
		}
		items = append(items, item)
	}
	return items, count, nil
}
func (r *SourceStreamRepo) CreateSource(ctx context.Context, item Source) (Source, error) {
	ensureID(&item.ID)
	now := time.Now().UnixMilli()
	d := sourceMetaData{Name: item.Name, Adapter: item.Protocol, Config: sourceConfig{Connection: json.RawMessage(item.Document), Streams: map[string]streamConfig{}}, ConfigRevision: 1, DesiredState: "enabled"}
	s := sourceStateData{Health: "unverified", Resources: json.RawMessage("[]"), Streams: map[string]json.RawMessage{}}
	err := streamRuntimeTransaction(ctx, r.db, false, func(tx *gorm.DB) error {
		raw, err := json.Marshal(d)
		if err != nil {
			return err
		}
		if err = tx.Create(&UnsMeta{ID: sourceKey(item.ID), Kind: "source", Data: raw, Revision: 1, CreatedAt: now, UpdatedAt: now}).Error; err != nil {
			return err
		}
		raw, err = json.Marshal(s)
		if err != nil {
			return err
		}
		return tx.Create(&UnsMeta{ID: sourceKey(item.ID), Kind: "source_state", Data: raw, Revision: 1, CreatedAt: now, UpdatedAt: now}).Error
	})
	if err != nil {
		return item, normalizeDBError(err)
	}
	return r.Source(ctx, item.ID)
}
func (r *SourceStreamRepo) ChangeSource(ctx context.Context, id, revision int64, change func(*gorm.DB, *Source) error) (Source, error) {
	var item Source
	err := streamRuntimeTransaction(ctx, r.db, true, func(tx *gorm.DB) error {
		row, data, err := sourceRow(tx, id, "UPDATE")
		if err != nil {
			return err
		}
		if row.Revision != revision {
			return ErrConflict
		}
		var format struct {
			SchemaVersion int `json:"schemaVersion"`
		}
		if json.Unmarshal(row.Data, &format) != nil || format.SchemaVersion == 1 {
			return ErrInvalidArgument
		}
		stateMeta, state, err := stateRow(tx, id, true)
		if err != nil {
			return err
		}
		item, err = projectSource(row, data, state)
		if err != nil {
			return err
		}
		if err = change(tx, &item); err != nil {
			return err
		}
		// The callback can rotate encrypted credentials in the same source row.
		_, fresh, err := sourceRow(tx, id, "")
		if err != nil {
			return err
		}
		data.Credentials = fresh.Credentials
		interruptionReason := ""
		configChanged := data.ConfigRevision != item.ConfigRevision
		if configChanged {
			interruptionReason = "source-config-changed-before-output"
			state.ConnectionCheck, state.DataCheck = nil, nil
			state.HealthLeaseUntil = 0
			item.ConnectionCheck, item.DataCheck = nil, nil
		}
		if item.DeletedAt > 0 || item.DesiredState == "disabled" {
			interruptionReason = "source-disabled-before-output"
		}
		data.Name = item.Name
		data.Adapter = item.Protocol
		data.Config.Connection = json.RawMessage(item.Document)
		data.ConfigRevision = item.ConfigRevision
		data.DesiredState = item.DesiredState
		row.DeletedAt = item.DeletedAt
		if err = saveMetaData(tx, &row, data); err != nil {
			return err
		}
		if interruptionReason != "" {
			if err = interruptUnpreparedSourceRuns(tx, item.ID, interruptionReason); err != nil {
				return err
			}
		}
		if configChanged || state.Health != item.Health || state.HealthMessage != item.HealthMessage || string(state.Resources) != item.Resources || state.CheckedAt != item.CheckedAt {
			state.Health = item.Health
			state.HealthMessage = item.HealthMessage
			state.Resources = json.RawMessage(item.Resources)
			state.CheckedAt = item.CheckedAt
			if err = saveMetaData(tx, &stateMeta, state); err != nil {
				return err
			}
		}
		item.Revision = row.Revision
		item.UpdatedAt = row.UpdatedAt
		return nil
	})
	return item, normalizeDBError(err)
}
func (r *SourceStreamRepo) ObserveSource(ctx context.Context, id, revision int64, health, message string, resources *string) error {
	return streamRuntimeTransaction(ctx, r.db, false, func(tx *gorm.DB) error {
		row, _, err := sourceRow(tx, id, "SHARE")
		if err != nil {
			return err
		}
		if row.Revision != revision {
			return ErrConflict
		}
		stateRow, state, err := stateRow(tx, id, true)
		if err != nil {
			return err
		}
		state.Health = health
		state.HealthMessage = message
		state.CheckedAt = time.Now().UnixMilli()
		if resources != nil {
			state.Resources = json.RawMessage(*resources)
		}
		return saveMetaData(tx, &stateRow, state)
	})
}

// Query Stream entries in JSONB, including inactive drafts; no relation table.
func streamQuery(db *gorm.DB) *gorm.DB {
	return db.Table(`(SELECT id, data->'config'->'streams' AS streams FROM public.uns_meta WHERE kind='source' AND deleted_at=0
 UNION ALL SELECT '0' AS id, jsonb_build_object(id,data) AS streams FROM public.uns_meta WHERE kind='stream' AND deleted_at=0) AS source`).Joins("CROSS JOIN LATERAL jsonb_each(source.streams) AS stream(key,value)").Where("COALESCE((stream.value->>'deletedAt')::bigint,0)=0").Where("stream.value->>'model' IN ?", []string{"script", "program", "publish", "subscribe", "request-reply"})
}

func (r *SourceStreamRepo) streamHistoryConfiguration(ctx context.Context, id int64) (Stream, streamConfig, error) {
	q := r.db.WithContext(ctx).Table(`(SELECT id,data->'config'->'streams' AS streams FROM public.uns_meta WHERE kind='source'
 UNION ALL SELECT '0' AS id,jsonb_build_object(id,data) AS streams FROM public.uns_meta WHERE kind='stream') AS source`).Joins("CROSS JOIN LATERAL jsonb_each(source.streams) AS stream(key,value)").Where("stream.key=?", sourceKey(id))
	var row streamEntry
	if err := q.Select("source.id AS source_id,stream.key AS id,stream.value AS data").Take(&row).Error; err != nil {
		return Stream{}, streamConfig{}, err
	}
	var c streamConfig
	if err := json.Unmarshal(row.Data, &c); err != nil {
		return Stream{}, c, err
	}
	sourceID, err := strconv.ParseInt(row.SourceID, 10, 64)
	if err != nil {
		return Stream{}, c, err
	}
	stream, err := projectStream(sourceID, row.ID, c)
	return stream, c, err
}

type streamEntry struct {
	SourceID string
	ID       string
	Data     json.RawMessage
}

func readStreamEntries(q *gorm.DB) ([]Stream, error) {
	var rows []streamEntry
	if err := q.Select("source.id AS source_id,stream.key AS id,stream.value AS data").Scan(&rows).Error; err != nil {
		return nil, err
	}
	items := []Stream{}
	for _, row := range rows {
		var c streamConfig
		if err := json.Unmarshal(row.Data, &c); err != nil {
			return nil, err
		}
		sourceID, err := strconv.ParseInt(row.SourceID, 10, 64)
		if err != nil {
			return nil, err
		}
		item, err := projectStream(sourceID, row.ID, c)
		if err != nil {
			return nil, err
		}
		items = append(items, item)
	}
	return items, nil
}

// Both saved draft and active deployment retain their Topic dependencies.
const streamTopicPredicate = `(stream.value->'topicIds' @> ?::jsonb OR EXISTS (SELECT 1 FROM jsonb_each(COALESCE(NULLIF(stream.value->'versions','null'::jsonb),'{}'::jsonb)) v WHERE v.key=stream.value->>'activeVersion' AND v.value->'document'->'topicIds' @> ?::jsonb))`

func (r *SourceStreamRepo) ListStreams(ctx context.Context, f StreamFilter) ([]Stream, int64, error) {
	q := streamQuery(r.db.WithContext(ctx))
	if f.SourceID > 0 {
		q = q.Where("(source.id=? OR "+scriptSourcePredicate("stream.value")+" OR stream.key IN (SELECT stream_id::text FROM public.uns_stream_source WHERE source_id=?))", sourceKey(f.SourceID), scriptSourceRef(f.SourceID), scriptSourceRef(f.SourceID), f.SourceID)
	}
	if f.Search != "" {
		q = q.Where("stream.value->>'name' ILIKE ?", "%"+f.Search+"%")
	}
	if f.Model != "" {
		q = q.Where("stream.value->>'model'=?", f.Model)
	}
	if f.Status != "" {
		q = q.Where("stream.value->>'status'=?", f.Status)
	}
	if f.TopicID > 0 {
		ref := fmt.Sprintf("[%d]", f.TopicID)
		q = q.Where("("+streamTopicPredicate+" OR stream.key IN (SELECT stream_id::text FROM public.uns_stream_topic WHERE topic_id=?))", ref, ref, f.TopicID)
	}
	var total int64
	if err := q.Count(&total).Error; err != nil {
		return nil, 0, err
	}
	offset, size := sourceStreamPage(f.Page, f.Size)
	items, err := readStreamEntries(q.Order("(stream.value->>'createdAt')::bigint DESC,stream.key DESC").Offset(offset).Limit(size))
	return items, total, err
}
func (r *SourceStreamRepo) Stream(ctx context.Context, id int64) (Stream, error) {
	items, err := readStreamEntries(streamQuery(r.db.WithContext(ctx)).Where("stream.key=?", sourceKey(id)))
	if err != nil {
		return Stream{}, err
	}
	if len(items) != 1 {
		return Stream{}, gorm.ErrRecordNotFound
	}
	return items[0], nil
}
func (r *SourceStreamRepo) SourceDependencies(ctx context.Context, id int64) ([]Stream, []StreamTopic, error) {
	_, data, err := sourceRow(r.db.WithContext(ctx), id, "")
	if err != nil {
		return nil, nil, err
	}
	standalone, err := r.scriptDependencies(ctx, id)
	if err != nil {
		return nil, nil, err
	}
	if data.Config.Streams == nil {
		data.Config.Streams = map[string]streamConfig{}
	}
	for key, c := range standalone {
		data.Config.Streams[key] = c
	}
	streams := []Stream{}
	topics := []StreamTopic{}
	for key, c := range data.Config.Streams {
		if c.DeletedAt != 0 {
			continue
		}
		item, err := projectStream(id, key, c)
		if err != nil {
			return nil, nil, err
		}
		if _, independent := standalone[key]; independent {
			item.SourceID = 0
		}
		streams = append(streams, item)
		if item.SourceID == 0 && item.Model != "script" {
			var refs []StreamTopic
			if err := r.db.WithContext(ctx).Where("stream_id=?", item.ID).Find(&refs).Error; err != nil {
				return nil, nil, err
			}
			topics = append(topics, refs...)
			continue
		}
		docs := []json.RawMessage{c.Document}
		for version, v := range c.Versions {
			if version == sourceKey(c.PendingVersion) || (c.Status == "enabled" && version == sourceKey(c.ActiveVersion)) {
				docs = append(docs, v.Document)
			}
		}
		seen := map[int64]bool{}
		for _, doc := range docs {
			var refs struct {
				TopicIDs []int64 `json:"topicIds"`
			}
			if err := json.Unmarshal(doc, &refs); err != nil {
				return nil, nil, err
			}
			for _, topic := range refs.TopicIDs {
				if !seen[topic] {
					topics = append(topics, StreamTopic{StreamID: item.ID, TopicID: topic})
					seen[topic] = true
				}
			}
		}
	}
	sort.Slice(streams, func(i, j int) bool { return streams[i].ID < streams[j].ID })
	sort.Slice(topics, func(i, j int) bool {
		if topics[i].StreamID == topics[j].StreamID {
			return topics[i].TopicID < topics[j].TopicID
		}
		return topics[i].StreamID < topics[j].StreamID
	})
	return streams, topics, nil
}
func validateStreamName(streams map[string]streamConfig, id, name string) error {
	for key, c := range streams {
		if key != id && c.DeletedAt == 0 && strings.EqualFold(c.Name, name) {
			return ErrConflict
		}
	}
	return nil
}
func (r *SourceStreamRepo) CreateStream(ctx context.Context, item Stream, topicIDs []int64) (Stream, error) {
	if item.Model == "script" {
		return r.createScriptStream(ctx, item)
	}
	ensureID(&item.ID)
	now := time.Now().UnixMilli()
	key := sourceKey(item.ID)
	err := streamRuntimeTransaction(ctx, r.db, false, func(tx *gorm.DB) error {
		row, data, err := sourceRow(tx, item.SourceID, "UPDATE")
		if err != nil {
			return err
		}
		count := 0
		for _, c := range data.Config.Streams {
			if c.DeletedAt == 0 {
				count++
			}
		}
		if count >= MaxSourceStreams {
			return ErrInvalidArgument
		}
		if err = validateStreamName(data.Config.Streams, key, item.Name); err != nil {
			return err
		}
		if data.Config.Streams == nil {
			data.Config.Streams = map[string]streamConfig{}
		}
		c := streamConfig{Name: item.Name, Model: item.Model, Document: json.RawMessage(item.Document), Revision: 1, Status: "draft", CreatedAt: now, UpdatedAt: now}
		if err = bindStreamSchema(tx, &c); err != nil {
			return err
		}
		data.Config.Streams[key] = c
		if err = saveMetaData(tx, &row, data); err != nil {
			return err
		}
		stateMeta, state, err := stateRow(tx, item.SourceID, true)
		if err != nil {
			return err
		}
		if state.Streams == nil {
			state.Streams = map[string]json.RawMessage{}
		}
		state.Streams[key] = json.RawMessage(`{"imported":false,"ackSeq":0}`)
		if err = saveMetaData(tx, &stateMeta, state); err != nil {
			return err
		}
		item, err = projectStream(item.SourceID, key, c)
		if err != nil {
			return err
		}
		return replaceStreamTopics(tx, item.ID, topicIDs)
	})
	return item, normalizeDBError(err)
}
func (r *SourceStreamRepo) changeStream(ctx context.Context, id, revision int64, change func(Source, *streamConfig) error, topicIDs ...[]int64) (Stream, error) {
	current, err := r.Stream(ctx, id)
	if err != nil {
		return Stream{}, err
	}
	if current.Model == "script" {
		return r.changeScriptStream(ctx, id, revision, change)
	}
	var result Stream
	err = streamRuntimeTransaction(ctx, r.db, false, func(tx *gorm.DB) error {
		row, data, err := sourceRow(tx, current.SourceID, "UPDATE")
		if err != nil {
			return err
		}
		key := sourceKey(id)
		c, ok := data.Config.Streams[key]
		if !ok || c.DeletedAt != 0 {
			return gorm.ErrRecordNotFound
		}
		if c.Revision != revision {
			return ErrConflict
		}
		_, state, err := stateRow(tx, current.SourceID, false)
		if err != nil {
			return err
		}
		source, err := projectSource(row, data, state)
		if err != nil {
			return err
		}
		if err = change(source, &c); err != nil {
			return err
		}
		if err = bindStreamSchema(tx, &c); err != nil {
			return err
		}
		if err = validateStreamName(data.Config.Streams, key, c.Name); err != nil {
			return err
		}
		c.Revision++
		c.UpdatedAt = time.Now().UnixMilli()
		data.Config.Streams[key] = c
		if err = saveMetaData(tx, &row, data); err != nil {
			return err
		}
		result, err = projectStream(current.SourceID, key, c)
		if err != nil {
			return err
		}
		if len(topicIDs) > 0 {
			return replaceStreamTopics(tx, id, topicIDs[0])
		}
		return nil
	})
	return result, normalizeDBError(err)
}
func (r *SourceStreamRepo) SaveStream(ctx context.Context, item Stream, revision int64, topicIDs []int64) (Stream, error) {
	return r.changeStream(ctx, item.ID, revision, func(source Source, c *streamConfig) error {
		if source.ID != item.SourceID || (c.Model == "script") != (item.Model == "script") {
			return ErrConflict
		}
		c.Name = item.Name
		c.Model = item.Model
		c.Document = json.RawMessage(item.Document)
		return nil
	}, topicIDs)
}
func (r *SourceStreamRepo) ActivateStream(ctx context.Context, id, revision, sourceRevision, versionID int64, document string, topicIDs []int64) (Stream, error) {
	return r.changeStream(ctx, id, revision, func(source Source, c *streamConfig) error {
		if c.Model != "script" && (source.ConfigRevision != sourceRevision || source.Health != "healthy") {
			return ErrConflict
		}
		if c.Versions == nil {
			c.Versions = map[string]streamDeployment{}
		}
		if versionID == 0 {
			ensureID(&versionID)
			c.Versions[sourceKey(versionID)] = streamDeployment{SourceRevision: source.ConfigRevision, Document: json.RawMessage(document), CreatedAt: time.Now().UnixMilli()}
		} else {
			v, ok := c.Versions[sourceKey(versionID)]
			if !ok || v.SourceRevision != source.ConfigRevision || !sameJSON(v.Document, []byte(document)) {
				return ErrConflict
			}
		}
		c.ActiveVersion = versionID
		c.Status = "enabled"
		return nil
	}, topicIDs)
}
func sameJSON(a, b []byte) bool {
	var left, right any
	if json.Unmarshal(a, &left) != nil || json.Unmarshal(b, &right) != nil {
		return false
	}
	x, _ := json.Marshal(left)
	y, _ := json.Marshal(right)
	return string(x) == string(y)
}
func (r *SourceStreamRepo) DisableStream(ctx context.Context, id, revision int64, remove bool) (Stream, error) {
	current, err := r.Stream(ctx, id)
	if err != nil {
		return Stream{}, err
	}
	if current.SourceID == 0 && current.Model != "script" {
		return r.disableProgramV2(ctx, id, revision, remove)
	}
	return r.changeStream(ctx, id, revision, func(_ Source, c *streamConfig) error {
		c.Status = "disabled"
		c.PendingVersion = 0
		if remove {
			c.DeletedAt = time.Now().UnixMilli()
		}
		return nil
	})
}
func (r *SourceStreamRepo) Versions(ctx context.Context, id int64, page, size int) ([]StreamVersion, int64, error) {
	current, config, err := r.streamHistoryConfiguration(ctx, id)
	if err != nil {
		return nil, 0, err
	}
	if current.SourceID == 0 && current.Model != "script" {
		var total int64
		q := r.db.WithContext(ctx).Model(&StreamVersion{}).Where("stream_id=?", id)
		if err := q.Count(&total).Error; err != nil {
			return nil, 0, err
		}
		offset, limit := sourceStreamPage(page, size)
		items := []StreamVersion{}
		err := q.Order("created_at DESC,id DESC").Offset(offset).Limit(limit).Find(&items).Error
		return items, total, err
	}
	items := []StreamVersion{}
	for key, v := range config.Versions {
		versionID, err := strconv.ParseInt(key, 10, 64)
		if err != nil {
			return nil, 0, err
		}
		items = append(items, projectDeployment(id, versionID, v))
	}
	sort.Slice(items, func(i, j int) bool { return items[i].ID > items[j].ID })
	total := int64(len(items))
	offset, limit := sourceStreamPage(page, size)
	if offset > len(items) {
		offset = len(items)
	}
	end := offset + limit
	if end > len(items) {
		end = len(items)
	}
	return items[offset:end], total, nil
}
func (r *SourceStreamRepo) Version(ctx context.Context, streamID, id int64) (StreamVersion, error) {
	current, config, err := r.streamHistoryConfiguration(ctx, streamID)
	if err != nil {
		return StreamVersion{}, err
	}
	if current.SourceID == 0 && current.Model != "script" {
		var v StreamVersion
		err := r.db.WithContext(ctx).Where("id=? AND stream_id=?", id, streamID).Take(&v).Error
		return v, err
	}
	v, ok := config.Versions[sourceKey(id)]
	if !ok {
		return StreamVersion{}, gorm.ErrRecordNotFound
	}
	return projectDeployment(streamID, id, v), nil
}

// ReleaseNumber 将不可变版本 ID 映射为发布序号。历史版本不物理删除，
// 因而后续发布不会改变旧版本的序号；调用方必须传入回执快照中的版本。
func (r *SourceStreamRepo) ReleaseNumber(ctx context.Context, streamID, versionID int64) (int64, error) {
	current, config, err := r.streamHistoryConfiguration(ctx, streamID)
	if err != nil {
		return 0, err
	}
	if current.SourceID == 0 && current.Model != "script" {
		if _, err := r.Version(ctx, streamID, versionID); err != nil {
			return 0, err
		}
		var release int64
		err := r.db.WithContext(ctx).Model(&StreamVersion{}).Where("stream_id=? AND id<=?", streamID, versionID).Count(&release).Error
		return release, err
	}
	if _, ok := config.Versions[sourceKey(versionID)]; !ok {
		return 0, gorm.ErrRecordNotFound
	}
	var release int64
	for key := range config.Versions {
		id, err := strconv.ParseInt(key, 10, 64)
		if err != nil {
			return 0, err
		}
		if id <= versionID {
			release++
		}
	}
	return release, nil
}

func projectDeployment(streamID, id int64, v streamDeployment) StreamVersion {
	sources, manifest := string(v.SourceManifest), string(v.ProgramManifest)
	if sources == "" {
		sources = "[]"
	}
	if manifest == "" {
		manifest = "{}"
	}
	return StreamVersion{ID: id, StreamID: streamID, SourceRevision: v.SourceRevision, SourceManifest: sources, ProgramManifest: manifest, ActivatedAt: v.ActivatedAt, Document: string(v.Document), CreatedAt: v.CreatedAt}
}
func (r *SourceStreamRepo) Credential(ctx context.Context, sourceID int64, id string) (SourceCredential, error) {
	_, data, err := sourceRow(r.db.WithContext(ctx), sourceID, "")
	if err != nil {
		return SourceCredential{}, err
	}
	c, ok := data.Credentials[id]
	if !ok {
		return c, gorm.ErrRecordNotFound
	}
	return c, nil
}
func (r *SourceStreamRepo) SaveCredential(ctx context.Context, item SourceCredential) error {
	if item.SourceID <= 0 || item.ID == "" || len(item.ID) > 128 || len(item.Ciphertext) == 0 {
		return ErrInvalidArgument
	}
	// Keep the row lock through the JSON write even when called outside
	// ChangeSource. A nested transaction preserves the caller's outer lock.
	return streamRuntimeTransaction(ctx, r.db, false, func(tx *gorm.DB) error {
		if err := tx.Exec("SELECT pg_advisory_xact_lock(hashtextextended(?,0))", "source-credential:"+item.ID).Error; err != nil {
			return err
		}
		var owners int64
		if err := metaQuery(tx, "source").Where("id<>? AND jsonb_exists(data->'credentials',?)", sourceKey(item.SourceID), item.ID).Count(&owners).Error; err != nil {
			return err
		}
		if owners > 0 {
			return ErrConflict
		}
		row, data, err := sourceRow(tx, item.SourceID, "UPDATE")
		if err != nil {
			return err
		}
		if data.Credentials == nil {
			data.Credentials = map[string]SourceCredential{}
		}
		data.Credentials[item.ID] = item
		raw, err := json.Marshal(data)
		if err != nil {
			return err
		}
		return metaQuery(tx, "source").Where("id=?", row.ID).Update("data", raw).Error
	})
}
func IsSourceStreamMissing(err error) bool { return errors.Is(err, gorm.ErrRecordNotFound) }

package repo

import (
	"context"
	"encoding/json"
	"fmt"
	"sort"
	"time"

	"gorm.io/gorm"
	"gorm.io/gorm/clause"
)

// 脚本 Stream 独立于 Source；持续采集 Stream 的协议配置仍由原采集仓库管理。
func scriptStreamRow(db *gorm.DB, id int64, lock string) (UnsMeta, streamConfig, error) {
	var row UnsMeta
	var config streamConfig
	q := metaQuery(db, "stream").Where("id=? AND deleted_at=0", sourceKey(id))
	if lock != "" {
		q = q.Clauses(clause.Locking{Strength: lock})
	}
	if err := q.Take(&row).Error; err != nil {
		return row, config, err
	}
	err := json.Unmarshal(row.Data, &config)
	return row, config, err
}

func scriptSourceRef(id int64) string { return fmt.Sprintf(`[{"sourceId":%d}]`, id) }
func scriptSourcePredicate(doc string) string {
	return "(" + doc + "->'sources' @> ?::jsonb OR EXISTS (SELECT 1 FROM jsonb_each(COALESCE(NULLIF(" + doc + "->'versions','null'::jsonb),'{}'::jsonb)) v WHERE v.key=" + doc + "->>'activeVersion' AND v.value->'document'->'sources' @> ?::jsonb))"
}

func currentSourcePredicate(doc string) string {
	return "((COALESCE(" + doc + "->'sources','[]'::jsonb) || COALESCE(" + doc + "->'document'->'sources','[]'::jsonb)) @> ?::jsonb OR EXISTS (SELECT 1 FROM jsonb_each(COALESCE(NULLIF(" + doc + "->'versions','null'::jsonb),'{}'::jsonb)) v WHERE (v.key=" + doc + "->>'pendingVersion' OR (" + doc + "->>'status'='enabled' AND v.key=" + doc + "->>'activeVersion')) AND (v.value->'document'->'sources' @> ?::jsonb OR v.value->'sourceManifest' @> ?::jsonb)))"
}

func (r *SourceStreamRepo) scriptDependencies(ctx context.Context, id int64) (map[string]streamConfig, error) {
	var rows []UnsMeta
	// Only drafts, active releases and pending deployments affect this mutation.
	// Retained releases remain auditable; rollback must acquire Source authority again.
	err := metaQuery(r.db.WithContext(ctx), "stream").Where("deleted_at=0").Where("("+currentSourcePredicate("data")+" OR id IN (SELECT stream_id::text FROM public.uns_stream_source WHERE source_id=?) OR EXISTS (SELECT 1 FROM public.uns_meta plan WHERE plan.kind='source_plan' AND plan.data->>'streamId'=uns_meta.id AND (plan.id=uns_meta.data->>'pendingVersion' OR (uns_meta.data->>'status'='enabled' AND plan.id=uns_meta.data->>'activeVersion')) AND plan.data->'sourceManifest' @> ?::jsonb))", scriptSourceRef(id), scriptSourceRef(id), scriptSourceRef(id), id, scriptSourceRef(id)).Find(&rows).Error
	if err != nil {
		return nil, err
	}
	result := map[string]streamConfig{}
	for _, row := range rows {
		var c streamConfig
		if e := json.Unmarshal(row.Data, &c); e != nil {
			return nil, e
		}
		result[row.ID] = c
	}
	return result, err
}

// 行锁覆盖依赖校验和提交，防止保存/启用与 Source 删除或凭据更新交错。
func lockScriptSources(tx *gorm.DB, document []byte, enabled bool) error {
	var doc struct {
		Sources []struct {
			SourceID       int64 `json:"sourceId"`
			ConfigRevision int64 `json:"configRevision"`
		} `json:"sources"`
	}
	if json.Unmarshal(document, &doc) != nil {
		return ErrInvalidArgument
	}
	sort.Slice(doc.Sources, func(i, j int) bool { return doc.Sources[i].SourceID < doc.Sources[j].SourceID })
	for _, binding := range doc.Sources {
		_, source, err := sourceRow(tx, binding.SourceID, "SHARE")
		if err != nil {
			return err
		}
		if source.ConfigRevision != binding.ConfigRevision {
			return ErrConflict
		}
	}
	return nil
}

func (r *SourceStreamRepo) createScriptStream(ctx context.Context, item Stream) (Stream, error) {
	if item.SourceID != 0 {
		return item, ErrInvalidArgument
	}
	ensureID(&item.ID)
	now := time.Now().UnixMilli()
	c := streamConfig{Name: item.Name, Model: item.Model, Document: json.RawMessage(item.Document), Revision: 1, Status: "draft", CreatedAt: now, UpdatedAt: now}
	err := r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		if err := lockScriptSources(tx, c.Document, false); err != nil {
			return err
		}
		data, err := json.Marshal(c)
		if err != nil {
			return err
		}
		return tx.Create(&UnsMeta{Kind: "stream", ID: sourceKey(item.ID), Data: data, Revision: 1, CreatedAt: now, UpdatedAt: now}).Error
	})
	if err != nil {
		return item, normalizeDBError(err)
	}
	return projectStream(0, sourceKey(item.ID), c)
}

func (r *SourceStreamRepo) changeScriptStream(ctx context.Context, id, revision int64, change func(Source, *streamConfig) error) (Stream, error) {
	var result Stream
	err := r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		row, c, err := scriptStreamRow(tx, id, "UPDATE")
		if err != nil {
			return err
		}
		if c.Revision != revision || c.Model != "script" {
			return ErrConflict
		}
		previousDocument, previousVersion, previousStatus := c.Document, c.ActiveVersion, c.Status
		if err = change(Source{}, &c); err != nil {
			return err
		}
		if c.Model != "script" {
			return ErrInvalidArgument
		}
		if c.DeletedAt == 0 {
			if !sameJSON(previousDocument, c.Document) {
				if err = lockScriptSources(tx, c.Document, false); err != nil {
					return err
				}
			}
			if c.Status == "enabled" && (previousStatus != "enabled" || previousVersion != c.ActiveVersion) {
				if err = lockScriptSources(tx, c.Versions[sourceKey(c.ActiveVersion)].Document, true); err != nil {
					return err
				}
			}
		}
		c.Revision++
		c.UpdatedAt = time.Now().UnixMilli()
		row.DeletedAt = c.DeletedAt
		if err = saveMetaData(tx, &row, c); err != nil {
			return err
		}
		result, err = projectStream(0, sourceKey(id), c)
		return err
	})
	return result, normalizeDBError(err)
}

func (r *SourceStreamRepo) streamConfiguration(ctx context.Context, stream Stream) (streamConfig, error) {
	if stream.Model == "script" {
		_, c, err := scriptStreamRow(r.db.WithContext(ctx), stream.ID, "")
		return c, err
	}
	_, data, err := sourceRow(r.db.WithContext(ctx), stream.SourceID, "")
	return data.Config.Streams[sourceKey(stream.ID)], err
}

func (r *SourceStreamRepo) AdmitScriptRun(ctx context.Context, run StreamRun) (bool, error) {
	created := false
	err := r.db.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		_, c, err := scriptStreamRow(tx, run.StreamID, "SHARE")
		if err != nil {
			return err
		}
		if c.Status != "enabled" || c.ActiveVersion != run.VersionID || c.Model != "script" {
			return ErrConflict
		}
		if err = lockScriptSources(tx, c.Versions[sourceKey(c.ActiveVersion)].Document, true); err != nil {
			return err
		}
		created, err = NewSourceStreamRepo(tx).ReserveRun(ctx, run)
		return err
	})
	return created, normalizeDBError(err)
}

// Package sourcestream defines protocol connections and independent UNS mappings.
// It does not reuse Node-RED flows or expose a separate driver registry.
package sourcestream

import (
	"crypto/tls"
	"encoding/json"
	"fmt"
	"net/url"
	"strconv"
	"strings"
	"unicode/utf8"

	"backend/internal/domain/common"
	"backend/internal/domain/unsmeta"
	"backend/internal/sourceresource"
	"backend/internal/streamexec"
)

type Protocol string
type AccessModel = sourceresource.AccessModel
type ConnectionRole string

const (
	ClientRole ConnectionRole = "client"
	ServerRole ConnectionRole = "server"
)

const (
	HTTP               Protocol    = "http-api"
	OAuth              Protocol    = "oauth2"
	MQTT               Protocol    = "mqtt"
	OPCUA              Protocol    = "opcua"
	ModbusTCP          Protocol    = "modbus-tcp"
	USBHID             Protocol    = "usb-hid"
	HIDTextResource                = "usb-hid:text"
	Publish            AccessModel = sourceresource.Publish
	Subscribe          AccessModel = sourceresource.Subscribe
	RequestReply       AccessModel = sourceresource.RequestReply
	ProgramAccess      AccessModel = "program"
	MaxScriptBytes                 = 128 * 1024
	MaxScriptTimeoutMs             = 30000
)

// ValidationError uses stable field/code values; HTTP and localization belong
// to the API boundary. Never include connection values or credentials in errors.
type ValidationError struct {
	Field string `json:"field"`
	Code  string `json:"code"`
}

func (e *ValidationError) Error() string { return e.Field + ": " + e.Code }

func invalid(field, code string) error { return &ValidationError{Field: field, Code: code} }

type MQTTOptions struct {
	CACertificate         string          `json:"caCertificate,omitempty"`
	PacketEnvelope        bool            `json:"packetEnvelope,omitempty"`
	Ephemeral             bool            `json:"-"`
	ClientID              string          `json:"clientId"`
	QoS                   int             `json:"qos,omitempty"`
	Subscriptions         map[string]byte `json:"subscriptions,omitempty"`
	TopicFilters          []string        `json:"topicFilters,omitempty"`
	RequestTopic          string          `json:"requestTopic,omitempty"`
	ReplyTopic            string          `json:"replyTopic,omitempty"`
	ReplyTopicField       string          `json:"replyTopicField,omitempty"`
	CorrelationField      string          `json:"correlationField,omitempty"`
	ServerSubscribeTopics []string        `json:"serverSubscribeTopics,omitempty"`
}
type OPCUAOptions struct {
	ServerCertificate  string            `json:"serverCertificate,omitempty"`
	SecurityMode       string            `json:"securityMode"`
	SecurityPolicy     string            `json:"securityPolicy"`
	NodeIDs            []string          `json:"nodeIds,omitempty"`
	SamplingIntervalMs int               `json:"samplingIntervalMs,omitempty"`
	ServerNodes        []OPCUAServerNode `json:"serverNodes,omitempty"`
}
type OPCUAServerNode struct {
	ID        string `json:"id"`
	Name      string `json:"name"`
	NodeClass string `json:"nodeClass"`
	DataType  string `json:"dataType"`
	Direction string `json:"direction"`
}
type ModbusRange = sourceresource.ModbusRange
type ModbusOptions = sourceresource.ModbusOptions

// SourceDefinition is the user-owned connection document. Authentication uses
// an opaque reference; secret material is never part of exported configuration.
type SourceDefinition struct {
	tlsConfig       *tls.Config
	Name            string                     `json:"name"`
	Description     string                     `json:"description"`
	Protocol        Protocol                   `json:"protocol"`
	SourceType      string                     `json:"sourceType,omitempty"`
	Role            ConnectionRole             `json:"role,omitempty"`
	Endpoint        string                     `json:"endpoint"`
	SQL             *SQLConnection             `json:"sql,omitempty"`
	CredentialRef   string                     `json:"credentialRef,omitempty"`
	RuntimeLocation string                     `json:"runtimeLocation"`
	HTTP            *HTTPConnection            `json:"http,omitempty"`
	MQTT            *MQTTConnection            `json:"mqtt,omitempty"`
	OPCUA           *OPCUAConnection           `json:"opcua,omitempty"`
	Modbus          *ModbusConnection          `json:"modbus,omitempty"`
	Extensions      map[string]json.RawMessage `json:"extensions,omitempty"`
	File            *FileSourceOptions         `json:"file,omitempty"`
	OpenProtocol    *OpenProtocolOptions       `json:"openProtocol,omitempty"`
}

func (d *SourceDefinition) UnmarshalJSON(raw []byte) error {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal(raw, &fields); err != nil || fields == nil {
		return invalid("document", "objectRequired")
	}
	for _, field := range []string{"sdkVersion", "configVersion", "supportedVersions"} {
		if _, exists := fields[field]; exists {
			return invalid(field, "unsupported")
		}
	}
	type connection SourceDefinition
	var value connection
	decoder := json.NewDecoder(strings.NewReader(string(raw)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&value); err != nil {
		return err
	}
	*d = SourceDefinition(value)
	return nil
}

// Optional collection fields preserve existing Source documents. New mappings
// own their collection configuration and override these values at execution.
type MQTTConnection = MQTTOptions
type OPCUAConnection = OPCUAOptions
type ModbusConnection = ModbusOptions

// RuntimeSource is assembled for a driver operation, never persisted as a Source.
type RuntimeSource = SourceDefinition

// Connection contains only endpoint and authentication/session settings.
func (d SourceDefinition) Connection() RuntimeSource {
	r := d
	if d.MQTT != nil {
		value := *d.MQTT
		r.MQTT = &value
	}
	if d.OPCUA != nil {
		value := *d.OPCUA
		r.OPCUA = &value
	}
	if d.Modbus != nil {
		value := *d.Modbus
		r.Modbus = &value
	}
	return r
}

func (d SourceDefinition) Validate() error {
	if _, err := d.tlsReferences(); err != nil {
		return err
	}
	for _, field := range []string{"ingress"} {
		if len(d.Extensions[field]) > 0 {
			return invalid("extensions."+field, "unsupportedCapability")
		}
	}
	return d.Connection().validate(false)
}
func (d SourceDefinition) ConnectionRole() ConnectionRole {
	if d.Role == "" {
		return ClientRole
	}
	return d.Role
}

func (d SourceDefinition) validate(collection bool) error {
	if d.OpenProtocol != nil && d.Protocol != OpenProtocol {
		return invalid("openProtocol", "protocolConfigMismatch")
	}
	if d.File != nil && d.Protocol != FileRead {
		return invalid("file", "protocolConfigMismatch")
	}
	if err := validateName(d.Name, d.Description); err != nil {
		return err
	}
	if d.RuntimeLocation != "local" {
		return invalid("runtimeLocation", "unsupported")
	}
	if d.ConnectionRole() != ClientRole && d.ConnectionRole() != ServerRole {
		return invalid("role", "unsupported")
	}
	if d.SourceType != "" {
		allowed := map[string]bool{"plant0-simctl": true, "pi-web-api": true, "plex-mes": true, "wms-rest": true, "sap-odata": true, "yonyou-yonbip": true, "kingdee-jdy": true, "ngp": true, "kingdee-k3cloud": true, "salesforce": true, "teamcenter": true, "hikvision-isapi": true}
		if !allowed[d.SourceType] || (d.Protocol != HTTP && d.Protocol != OAuth) || d.ConnectionRole() != ClientRole {
			return invalid("sourceType", "unsupported")
		}
		if d.SourceType == "plant0-simctl" && (d.Protocol != HTTP || d.CredentialRef != "" || d.HTTP == nil || d.HTTP.Authentication != "none" || len(d.HTTP.Headers) != 0) {
			return invalid("http.authentication", "publicReadOnlySource")
		}
	}
	if d.ConnectionRole() == ServerRole && d.Protocol != MQTT && d.Protocol != OPCUA && d.Protocol != HTTP {
		return invalid("role", "sourceUnsupported")
	}
	u, err := url.Parse(d.Endpoint)
	if err != nil || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" {
		return invalid("endpoint", "invalid")
	}
	if u.Port() != "" {
		port, err := strconv.Atoi(u.Port())
		if err != nil || port < 1 || port > 65535 {
			return invalid("endpoint", "invalidPort")
		}
	}
	if d.Protocol != EdgeSQL && d.SQL != nil {
		return invalid("sql", "protocolConfigMismatch")
	}
	if d.Protocol != HTTP && d.Protocol != OAuth && d.HTTP != nil {
		return invalid("http", "protocolConfigMismatch")
	}
	// A Server Source selects a platform listener, never an arbitrary bind address.
	if d.ConnectionRole() == ServerRole && ((d.Protocol == MQTT && d.Endpoint != "mqtt://managed") || (d.Protocol == OPCUA && d.Endpoint != "opc.tcp://managed") || (d.Protocol == HTTP && d.Endpoint != "http://managed")) {
		return invalid("endpoint", "managedServerRequired")
	}
	switch d.Protocol {
	case OpenProtocol:
		return validateOpenProtocol(d)
	case EdgeSQL:
		return validateSQLConnection(d, u)
	case FileRead:
		return d.validateFileSource(u)
	case USBHID:
		_, legacyErr := d.HIDDevice()
		if (!IsHIDDeviceKey(d.Endpoint) && legacyErr != nil) || d.CredentialRef != "" || d.MQTT != nil || d.OPCUA != nil || d.Modbus != nil {
			return invalid("endpoint", "invalid")
		}
	case HTTP, OAuth:
		if d.HTTP == nil || d.MQTT != nil || d.OPCUA != nil || d.Modbus != nil || !validHTTPBase(d.Endpoint) {
			return invalid("http", "invalid")
		}
		if err := ValidateSourceHTTPHeaders(d.HTTP.Headers); err != nil {
			return err
		}
		if d.SourceType == "pi-web-api" {
			if err := validatePIBinding(d); err != nil {
				return err
			}
		}
		if d.SourceType == "teamcenter" {
			if err := validateTeamcenterFiles(d); err != nil {
				return err
			}
		}
		if d.SourceType == "salesforce" {
			if _, err := salesforceQueries(d); err != nil {
				return err
			}
		}
		if d.ConnectionRole() == ServerRole && len(d.HTTP.Headers) > 0 {
			return invalid("http.headers", "clientOnly")
		}
		parameters, err := json.Marshal(d.HTTP.Parameters)
		if err != nil || len(parameters) > 64*1024 || len(d.HTTP.Parameters) > 128 {
			return invalid("http.parameters", "invalid")
		}
		for key := range d.HTTP.Parameters {
			if strings.TrimSpace(key) == "" || len(key) > 128 || strings.ContainsAny(key, "\x00\r\n") {
				return invalid("http.parameters", "invalid")
			}
		}
		if d.HTTP.Port < 0 || d.HTTP.Port > 65535 || d.ConnectionRole() != ServerRole && (d.HTTP.Port != 0 || d.HTTP.Anonymous) {
			return invalid("http.port", "serverOnly")
		}
		if d.ConnectionRole() == ServerRole {
			if d.HTTP.OAuth != nil || d.HTTP.CACertificate != "" || (d.HTTP.Anonymous && d.HTTP.Authentication != "" && d.HTTP.Authentication != "none") || (!d.HTTP.Anonymous && d.HTTP.Authentication != "" && d.HTTP.Authentication != "bearer") {
				return invalid("http.authentication", "invalidServerAuthentication")
			}
			return nil
		}
		if _, err := publicCertificates(d.HTTP.CACertificate, true); err != nil {
			return invalid("http.caCertificate", "invalid")
		}
		if d.Protocol == OAuth {
			if d.HTTP.OAuth == nil || d.HTTP.Authentication != "" {
				return invalid("http.oauth", "invalid")
			}
			return d.HTTP.OAuth.validate()
		}
		if d.HTTP.OAuth != nil {
			return invalid("http.oauth", "unsupported")
		}
		switch d.HTTP.Authentication {
		case "none", "basic", "bearer", "custom", "http":
			return nil
		}
		return invalid("http.authentication", "unsupported")
	case MQTT:
		if d.MQTT == nil || d.OPCUA != nil || d.Modbus != nil {
			return invalid("mqtt", "protocolConfigMismatch")
		}
		if (u.Scheme != "mqtt" && u.Scheme != "mqtts") || (u.Path != "" && u.Path != "/") {
			return invalid("endpoint", "invalidScheme")
		}
		m := d.MQTT
		if m.CACertificate != "" {
			if _, err := publicCertificates(m.CACertificate, true); err != nil || u.Scheme != "mqtts" {
				return invalid("mqtt.caCertificate", "invalid")
			}
		}
		if strings.TrimSpace(m.ClientID) == "" || m.QoS < 0 || m.QoS > 2 {
			return invalid("mqtt", "invalid")
		}
		for filter, qos := range m.Subscriptions {
			if !validMQTTTopic(filter, true) || qos > 2 {
				return invalid("mqtt.subscriptions", "invalid")
			}
		}
		for _, filter := range m.TopicFilters {
			if !validMQTTTopic(filter, true) {
				return invalid("mqtt.topicFilters", "invalid")
			}
		}
		if d.ConnectionRole() == ServerRole {
			if len(m.TopicFilters)+len(m.ServerSubscribeTopics) > 1000 {
				return invalid("mqtt", "tooManyResources")
			}
			for _, topic := range append(append([]string{}, m.TopicFilters...), m.ServerSubscribeTopics...) {
				if !validMQTTTopic(topic, true) || strings.HasPrefix(topic, "$") || strings.HasPrefix(topic, "/") {
					return invalid("mqtt", "invalidServerTopic")
				}
			}
			for _, topic := range m.ServerSubscribeTopics {
				if strings.ContainsAny(topic, "+#") {
					return invalid("mqtt.serverSubscribeTopics", "concreteTopicRequired")
				}
			}
		} else if len(m.ServerSubscribeTopics) > 0 {
			return invalid("mqtt.serverSubscribeTopics", "serverOnly")
		}
		if m.RequestTopic != "" || m.ReplyTopic != "" || m.ReplyTopicField != "" || m.CorrelationField != "" {
			if !validMQTTTopic(m.RequestTopic, false) || !validMQTTTopic(m.ReplyTopic, false) || !safeField(m.CorrelationField) {
				return invalid("mqtt", "incompleteRequestReply")
			}
			hasReplyTemplate := strings.Count(m.ReplyTopic, "{correlationId}") == 1
			if strings.Contains(m.ReplyTopic, "{") || strings.Contains(m.ReplyTopic, "}") {
				if !hasReplyTemplate || strings.ReplaceAll(m.ReplyTopic, "{correlationId}", "") == "" {
					return invalid("mqtt.replyTopic", "invalidTemplate")
				}
			}
			if hasReplyTemplate != (m.ReplyTopicField != "") || m.ReplyTopicField != "" && !safeField(m.ReplyTopicField) {
				return invalid("mqtt.replyTopicField", "templateRequired")
			}
			if m.RequestTopic == m.ReplyTopic {
				return invalid("mqtt.replyTopic", "requestReplyLoop")
			}
			if d.ConnectionRole() == ServerRole && (strings.HasPrefix(m.RequestTopic, "$") || strings.HasPrefix(m.ReplyTopic, "$") || strings.HasPrefix(m.RequestTopic, "/") || strings.HasPrefix(m.ReplyTopic, "/")) {
				return invalid("mqtt", "invalidServerTopic")
			}
		}
	case OPCUA:
		if d.OPCUA == nil || d.MQTT != nil || d.Modbus != nil {
			return invalid("opcua", "protocolConfigMismatch")
		}
		if u.Scheme != "opc.tcp" {
			return invalid("endpoint", "invalidScheme")
		}
		o := d.OPCUA
		if certificates, err := publicCertificates(o.ServerCertificate, false); err != nil || len(certificates) > 1 {
			return invalid("opcua.serverCertificate", "invalid")
		}
		if collection && (o.SamplingIntervalMs < 100 || o.SamplingIntervalMs > 3600000) {
			return invalid("opcua.samplingIntervalMs", "outOfRange")
		}
		if (o.SecurityMode == "None" && o.SecurityPolicy != "None") ||
			(o.SecurityMode != "None" && o.SecurityMode != "Sign" && o.SecurityMode != "SignAndEncrypt") ||
			(o.SecurityMode != "None" && o.SecurityPolicy != "Basic256Sha256" && o.SecurityPolicy != "Aes128_Sha256_RsaOaep" && o.SecurityPolicy != "Aes256_Sha256_RsaPss") {
			return invalid("opcua.securityPolicy", "invalid")
		}
		for _, node := range o.NodeIDs {
			if strings.TrimSpace(node) == "" {
				return invalid("opcua.nodeIds", "invalid")
			}
		}
		if d.ConnectionRole() == ServerRole {
			if len(o.ServerNodes) == 0 || len(o.ServerNodes) > 1000 || len(o.NodeIDs) > 1000 {
				return invalid("opcua.serverNodes", "outOfRange")
			}
			if !((o.SecurityMode == "None" && o.SecurityPolicy == "None") || (o.SecurityMode == "SignAndEncrypt" && o.SecurityPolicy == "Basic256Sha256")) {
				return invalid("opcua.securityPolicy", "unsupportedServerSecurity")
			}
			seen := map[string]bool{}
			for _, node := range o.ServerNodes {
				if node.ID == "" || len(node.ID) > common.NameMaxLen || seen[node.ID] {
					return invalid("opcua.serverNodes.id", "duplicateOrEmpty")
				}
				for i, ch := range node.ID {
					letter := ch >= 'a' && ch <= 'z' || ch >= 'A' && ch <= 'Z'
					if !letter && (i == 0 || !(ch >= '0' && ch <= '9' || ch == '_' || ch == '-')) {
						return invalid("opcua.serverNodes.id", "invalid")
					}
				}
				seen[node.ID] = true
				if strings.TrimSpace(node.Name) == "" || common.ExceedNameLimit(node.Name) {
					return invalid("opcua.serverNodes.name", "invalid")
				}
				if node.NodeClass != "Variable" && node.NodeClass != "Method" ||
					(node.DataType != "Double" && node.DataType != "Int32" && node.DataType != "Boolean" && node.DataType != "String") ||
					(node.Direction != "ingress" && node.Direction != "egress" && node.Direction != "bidirectional") ||
					(node.NodeClass == "Method" && (node.DataType != "String" || node.Direction != "ingress")) {
					return invalid("opcua.serverNodes", "invalid")
				}
			}
			for _, id := range o.NodeIDs {
				if !seen[id] {
					return invalid("opcua.nodeIds", "outsideDeclaredNodes")
				}
			}
		} else if len(o.ServerNodes) > 0 {
			return invalid("opcua.serverNodes", "serverOnly")
		}
	case ModbusTCP:
		if d.Modbus == nil || d.MQTT != nil || d.OPCUA != nil {
			return invalid("modbus", "protocolConfigMismatch")
		}
		if u.Scheme != "tcp" || (u.Path != "" && u.Path != "/") {
			return invalid("endpoint", "invalidScheme")
		}
		m := d.Modbus
		if m.UnitID < 1 || m.UnitID > 247 {
			return invalid("modbus.unitId", "outOfRange")
		}
		if collection && (m.PollIntervalMs < 100 || m.PollIntervalMs > 3600000) {
			return invalid("modbus.pollIntervalMs", "outOfRange")
		}
		seen := map[string]bool{}
		for i, r := range m.Ranges {
			field := fmt.Sprintf("modbus.ranges[%d]", i)
			if r.UnitID != nil && (*r.UnitID < 1 || *r.UnitID > 247) {
				return invalid(field+".unitId", "outOfRange")
			}
			if r.Writable != nil && *r.Writable && r.Table != "holding-register" && r.Table != "coil" {
				return invalid(field+".writable", "readOnlyTable")
			}
			if r.ID == "" || seen[r.ID] {
				return invalid(field+".id", "duplicateOrEmpty")
			}
			seen[r.ID] = true
			maxQuantity := 125
			switch r.Table {
			case "holding-register", "input-register":
			case "coil", "discrete-input":
				maxQuantity = 2000
			default:
				return invalid(field+".table", "unsupported")
			}
			if r.Address < 0 || r.Address > 65535 || r.Quantity < 1 || r.Quantity > maxQuantity || r.Address+r.Quantity > 65536 {
				return invalid(field, "outOfRange")
			}
		}
	default:
		return invalid("protocol", "unsupported")
	}
	return nil
}

// The configured origin is the authority; scripts can only supply paths under
// its prefix. Address validation is repeated at dial time by the HTTP client.
func validHTTPBase(raw string) bool {
	u, err := url.Parse(raw)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Opaque != "" || strings.Contains(u.Path, "\\") {
		return false
	}
	for _, part := range strings.Split(u.Path, "/") {
		if part == "." || part == ".." {
			return false
		}
	}
	return true
}

func (d SourceDefinition) HTTPAuthentication() string {
	if d.HTTP == nil {
		return ""
	}
	if d.ConnectionRole() == ServerRole {
		if d.HTTP.Anonymous {
			return "none"
		}
		if d.HTTP.Authentication == "" {
			return "bearer"
		}
	}
	return d.HTTP.Authentication
}

// Protocol-level eligibility is not device capability discovery. Deployment
// must also validate each selected native resource and operation with the driver.
func (d SourceDefinition) Supports(model AccessModel) bool {
	if d.Validate() != nil {
		return false
	}
	if d.Protocol == USBHID {
		return model == Publish
	}
	switch model {
	case Publish, Subscribe:
		return true
	case RequestReply:
		return d.Protocol != MQTT || d.MQTT.RequestTopic != ""
	default:
		return false
	}
}

type ScriptDefinition struct {
	Code      string `json:"code"`
	TimeoutMs int    `json:"timeoutMs"`
}

type SourceBinding struct {
	Alias          string `json:"alias"`
	SourceID       int64  `json:"sourceId"`
	ConfigRevision int64  `json:"configRevision"`
}

const ScriptMode AccessModel = "script"

const MaxScriptSources = 16

type StreamDefinition struct {
	legacyProgram         bool
	ProgramSources        []ProgramSourceBinding     `json:"-"`
	ProgramSourceBindings []ProgramSourceBinding     `json:"-"`
	Sources               []SourceBinding            `json:"sources,omitempty"`
	Collection            *CollectionDefinition      `json:"collection"`
	Name                  string                     `json:"name"`
	Description           string                     `json:"description"`
	SourceID              int64                      `json:"sourceId"`
	Model                 AccessModel                `json:"model"`
	NativeResourceRef     string                     `json:"nativeResourceRef"`
	NativeResourceRefs    []string                   `json:"nativeResourceRefs,omitempty"`
	TopicIDs              []int64                    `json:"topicIds"`
	MetadataTarget        *unsmeta.Mapping           `json:"metadataTarget,omitempty"`
	Script                ScriptDefinition           `json:"script"`
	ResponseScript        *ScriptDefinition          `json:"responseScript,omitempty"`
	Program               *ProgramDefinition         `json:"program,omitempty"`
	Extensions            map[string]json.RawMessage `json:"extensions,omitempty"`
}

// IsCompleteProgram checks the current in-memory representation, never a model version.
func (d StreamDefinition) IsCompleteProgram() bool {
	return (d.Model == "" || d.Model == ProgramAccess) && d.SourceID == 0 && d.Program == nil && d.ResponseScript == nil &&
		d.NativeResourceRef == "" && d.NativeResourceRefs == nil && d.TopicIDs == nil && d.Sources == nil && d.Collection == nil && d.MetadataTarget == nil
}

// Public program documents share one script object and binding contract.
// Persisted historical flat releases use decodeStoredProgram, never this entry.
func (d *StreamDefinition) UnmarshalJSON(raw []byte) error {
	var object map[string]json.RawMessage
	if err := json.Unmarshal(raw, &object); err != nil || object == nil {
		return invalid("document", "objectRequired")
	}
	for _, field := range []string{"sdkVersion", "configVersion", "supportedVersions", "model", "sourceId", "collection", "metadataTarget", "program", "responseScript", "topicIds", "nativeResourceRef", "nativeResourceRefs", "timeoutMs"} {
		if _, exists := object[field]; exists {
			return invalid(field, "unsupported")
		}
	}
	for _, field := range []string{"script", "sources", "sourceBindings"} {
		if value, exists := object[field]; exists && strings.TrimSpace(string(value)) == "null" {
			return invalid(field, "invalid")
		}
	}
	var flat struct {
		Name           string                     `json:"name"`
		Description    string                     `json:"description"`
		Script         ScriptDefinition           `json:"script"`
		Sources        []ProgramSourceBinding     `json:"sources,omitempty"`
		SourceBindings []ProgramSourceBinding     `json:"sourceBindings,omitempty"`
		Extensions     map[string]json.RawMessage `json:"extensions,omitempty"`
	}
	decoder := json.NewDecoder(strings.NewReader(string(raw)))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&flat); err != nil {
		return err
	}
	*d = StreamDefinition{Name: flat.Name, Description: flat.Description, Model: ProgramAccess,
		Script: flat.Script, ProgramSources: flat.Sources, ProgramSourceBindings: flat.SourceBindings, Extensions: flat.Extensions}
	return d.validateProgramBindings()
}

func (d StreamDefinition) MarshalJSON() ([]byte, error) {
	if err := d.validateCompleteProgram(false); err != nil {
		return nil, err
	}
	return json.Marshal(struct {
		Name           string                     `json:"name"`
		Description    string                     `json:"description"`
		Script         ScriptDefinition           `json:"script"`
		Sources        []ProgramSourceBinding     `json:"sources,omitempty"`
		SourceBindings []ProgramSourceBinding     `json:"sourceBindings,omitempty"`
		Extensions     map[string]json.RawMessage `json:"extensions,omitempty"`
	}{d.Name, d.Description, d.Script, d.ProgramSources, d.ProgramSourceBindings, d.Extensions})
}

func (d StreamDefinition) validateCompleteProgram(required bool) error {
	if err := d.validateProgramBindings(); err != nil {
		return err
	}
	if d.SourceID != 0 || d.Model != "" && d.Model != ProgramAccess || d.Program != nil || d.ResponseScript != nil ||
		d.NativeResourceRef != "" || d.NativeResourceRefs != nil || d.TopicIDs != nil || d.Sources != nil || d.Collection != nil || d.MetadataTarget != nil {
		return invalid("document", "completeProgramOnly")
	}
	maximum := MaxScriptTimeoutMs
	if d.legacyProgram {
		maximum = streamexec.MaxProgramTimeoutMs
	}
	if d.Script.TimeoutMs > maximum {
		return invalid("timeoutMs", "outOfRange")
	}
	return validateScriptWithTimeout(d.Script, "script", required, maximum)
}

// ResourceRefs is the single source of input selection. Request/reply and
// subscription operations remain singular; publication may select many inputs.
func (d StreamDefinition) ResourceRefs() []string {
	if len(d.NativeResourceRefs) > 0 {
		return d.NativeResourceRefs
	}
	if d.NativeResourceRef != "" {
		return []string{d.NativeResourceRef}
	}
	return nil
}

func (d StreamDefinition) MatchesResource(ref string) bool {
	for _, selected := range d.ResourceRefs() {
		if selected == ref {
			return true
		}
		if d.Model == Publish && strings.HasPrefix(selected, "mqtt:") && strings.HasPrefix(ref, "mqtt:") &&
			mqttFilterMatches(strings.TrimPrefix(selected, "mqtt:"), strings.TrimPrefix(ref, "mqtt:")) {
			return true
		}
	}
	return false
}

// MQTT filters select inputs; the event and script context retain the actual
// Topic name. Wildcards never apply to OPC UA/Modbus IDs or downlink operations.
func mqttFilterMatches(filter, topic string) bool {
	if !validMQTTTopic(filter, true) || !validMQTTTopic(topic, false) {
		return false
	}
	if strings.HasPrefix(topic, "$") && (filter[0] == '+' || filter[0] == '#') {
		return false
	}
	levels, names := strings.Split(filter, "/"), strings.Split(topic, "/")
	for i, level := range levels {
		if level == "#" {
			return true
		}
		if i >= len(names) || (level != "+" && level != names[i]) {
			return false
		}
	}
	return len(levels) == len(names)
}

// ValidateDraft checks the document shape, not connectivity or deployment.
// Drafts may omit references so users can save unfinished work.
func (d StreamDefinition) ValidateDraft() error {
	if err := validateName(d.Name, d.Description); err != nil {
		return err
	}
	return d.validateCompleteProgram(false)
}

// ValidateDeployment is a pure first gate. The service must additionally check
// source revision/health, native operation capabilities, Topic ACL/schema and
// script compilation. Passing this function alone never means "running".
func (d StreamDefinition) ValidateDeployment(sourceID int64, source SourceDefinition) error {
	if err := d.ValidateDraft(); err != nil {
		return err
	}
	return d.validateCompleteProgram(true)
}

func validateName(name, description string) error {
	if strings.TrimSpace(name) == "" || common.ExceedNameLimit(name) {
		return invalid("name", "invalidLength")
	}
	if common.ExceedDescLimit(description) {
		return invalid("description", "invalidLength")
	}
	return nil
}

func validateScript(script ScriptDefinition, field string, required bool) error {
	return validateScriptWithTimeout(script, field, required, MaxScriptTimeoutMs)
}

func validateScriptWithTimeout(script ScriptDefinition, field string, required bool, maxTimeoutMs int) error {
	if required && strings.TrimSpace(script.Code) == "" {
		return invalid(field+".code", "required")
	}
	if len(script.Code) > MaxScriptBytes {
		return invalid(field+".code", "tooLarge")
	}
	if script.TimeoutMs < 1 || script.TimeoutMs > maxTimeoutMs {
		return invalid(field+".timeoutMs", "outOfRange")
	}
	return nil
}

func safeField(field string) bool {
	for _, part := range strings.Split(field, ".") {
		if part == "" || part == "__proto__" || part == "prototype" || part == "constructor" {
			return false
		}
		for _, r := range part {
			if !((r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_') {
				return false
			}
		}
	}
	return true
}

func validMQTTTopic(topic string, filter bool) bool {
	if topic == "" || len(topic) > 65535 || !utf8.ValidString(topic) || strings.ContainsRune(topic, '\x00') {
		return false
	}
	levels := strings.Split(topic, "/")
	for i, level := range levels {
		if strings.ContainsAny(level, "+#") && (!filter || (level != "+" && !(level == "#" && i == len(levels)-1))) {
			return false
		}
	}
	return true
}

// Package sourceresource defines native resources shared by Source discovery
// and immutable Stream publications.
package sourceresource

import "encoding/json"

type AccessModel string

const (
	Publish      AccessModel = "publish"
	Subscribe    AccessModel = "subscribe"
	RequestReply AccessModel = "request-reply"
)

type NativeResource struct {
	ID       string          `json:"id"`
	Name     string          `json:"name"`
	Models   []AccessModel   `json:"models"`
	Schema   json.RawMessage `json:"schema,omitempty"`
	Metadata map[string]any  `json:"metadata,omitempty"`
}

type ModbusRange struct {
	ID       string `json:"id"`
	UnitID   *int   `json:"unitId,omitempty"`
	Writable *bool  `json:"writable,omitempty"`
	Table    string `json:"table"`
	Address  int    `json:"address"`
	Quantity int    `json:"quantity"`
}

type ModbusOptions struct {
	UnitID         int           `json:"unitId"`
	PollIntervalMs int           `json:"pollIntervalMs,omitempty"`
	Ranges         []ModbusRange `json:"ranges,omitempty"`
}

func (r ModbusRange) EffectiveUnitID(fallback int) int {
	if r.UnitID != nil {
		return *r.UnitID
	}
	return fallback
}

func (r ModbusRange) CanWrite() bool {
	if r.Writable != nil && !*r.Writable {
		return false
	}
	return (r.Table == "holding-register" && r.Quantity <= 123) || (r.Table == "coil" && r.Quantity <= 1968)
}

func (r ModbusRange) NativeResource(defaultUnitID int) NativeResource {
	models := []AccessModel{Publish, RequestReply}
	writable := r.CanWrite()
	if writable {
		models = append(models, Subscribe)
	}
	return NativeResource{
		ID: "modbus:" + r.ID, Name: r.ID, Models: models,
		Metadata: map[string]any{
			"unitId": r.EffectiveUnitID(defaultUnitID), "table": r.Table,
			"address": r.Address, "quantity": r.Quantity, "writable": writable,
		},
	}
}

