// Generate only the metadata contract, preserving the colleague-owned adapters.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const backend = join(root, 'backend');
const temp = mkdtempSync(join(tmpdir(), 'tier0-uns-metadata-api-'));
const home = join(temp, 'templates');
const read = (path) => readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
const run = (args) => execFileSync(process.env.GOCTL || 'goctl', args, { cwd: temp, stdio: 'pipe' });
writeFileSync(join(temp, 'go.mod'), 'module backend\n\ngo 1.25.0\n');
copyFileSync(join(backend, 'http/core/uns-metadata.api'), join(temp, 'core.api'));
copyFileSync(join(backend, 'http/openapi/v1/uns-metadata.api'), join(temp, 'openapi.api'));
writeFileSync(join(temp, 'backend.api'), 'syntax = "v1"\nimport "core.api"\nimport "openapi.api"\n');
run(['api', 'validate', '--api', 'backend.api']);
run(['template', 'init', '--home', home]);
writeFileSync(join(home, 'api/handler.tpl'), `// Code generated by goctl. DO NOT EDIT.
// goctl {{.version}}
package {{.PkgName}}
import (
 "net/http"
 respx "backend/internal/httpx"
 gozerohttpx "github.com/zeromicro/go-zero/rest/httpx"
 {{.ImportPackages}}
)
func {{.HandlerName}}(svcCtx *svc.ServiceContext) http.HandlerFunc {
 return func(w http.ResponseWriter, r *http.Request) {
  var req types.{{.RequestType}}
  if err := respx.ParseSourceStreamRequest(r, &req); err != nil {
   respx.WriteError(w, respx.NewHTTPError(http.StatusBadRequest, "UnsMeta.invalid")); return
  }
  l := {{.LogicName}}.New{{.LogicType}}(r.Context(), svcCtx)
  resp, err := l.{{.Call}}(&req)
  if err != nil { respx.WriteError(w, err); return }
  gozerohttpx.OkJson(w, resp)
 }
}
`);
writeFileSync(join(home, 'api/logic.tpl'), `// Code scaffolded by goctl. Safe to edit.
// goctl {{.version}}
package {{.pkgName}}
import ({{.imports}})
type {{.logic}} struct { logx.Logger; ctx context.Context; svcCtx *svc.ServiceContext }
func New{{.logic}}(ctx context.Context, svcCtx *svc.ServiceContext) *{{.logic}} {
 return &{{.logic}}{Logger: logx.WithContext(ctx), ctx: ctx, svcCtx: svcCtx}
}
func (l *{{.logic}}) {{.function}}({{.request}}) {{.responseType}} {
 return execute(l.ctx, l.svcCtx, req)
}
`);
run(['api', 'go', '--api', 'backend.api', '--dir', temp, '--home', home, '--style=goZero']);
const typesFile = join(backend, 'internal/types/types.go');
const pattern = /type (\w+) struct \{[\s\S]*?\n\}/g;
const generated = [...read(join(temp, 'internal/types/types.go')).matchAll(pattern)];
const names = new Set(generated.map((item) => item[1]));
assert.ok(names.has('UnsMetaSaveReq') && names.has('UnsMetaEnvelope'));
const types = read(typesFile).replace(pattern, (block, name) => names.has(name) ? '' : block).trimEnd();
writeFileSync(typesFile, `${types}\n\n${generated.map((item) => item[0]).join('\n\n')}\n`);

// Match the Source/Stream generator's Swagger 2 plugin.
if (process.env.GOCTL_SWAGGER) {
 run(['api','plugin','--api','backend.api','--dir',temp,'--plugin',`${process.env.GOCTL_SWAGGER} swagger --filename metadata-swagger.json`]);
} else {
 run(['api','swagger','--api','backend.api','--dir',temp,'--filename','metadata-swagger.json']);
}
const generatedSwagger = JSON.parse(read(join(temp, 'metadata-swagger.json')));
assert.equal(generatedSwagger.swagger, '2.0');
const swaggerFile = join(backend, 'http/swagger.json');
const swagger = JSON.parse(read(swaggerFile));
Object.assign(swagger.paths, generatedSwagger.paths);
for (const key of Object.keys(swagger.paths)) { if (/^\/api\/core\/uns\/(metadata(?:\/|$)|collections(?:\/|$)|topics\/validate$)/.test(key)) delete swagger.paths[key]; }
Object.assign(swagger.definitions ||= {}, generatedSwagger.definitions);
writeFileSync(swaggerFile, JSON.stringify(swagger, null, 2) + '\n');
// This contract has no @auth annotations; permission bindings live in seed.go.

const routeFile = join(backend, 'internal/handler/routes.go');
const routePattern = /\tserver\.AddRoutes\([\s\S]*?\n\t\)/g;
const generatedRoutes = read(join(temp, 'internal/handler/routes.go'));
const blocks = generatedRoutes.match(routePattern)?.filter((block) => /(?:core|openapiv1)unsmeta\./.test(block));
assert.ok(blocks?.length);
let routes = read(routeFile).replace(routePattern, (block) => /(?:core|openapiv1)unsmeta\./.test(block) ? '' : block);
for (const imp of ['coreunsmeta "backend/internal/handler/core/unsmeta"', 'openapiv1unsmeta "backend/internal/handler/openapi/v1/unsmeta"']) {
 const alias=imp.split(' ')[0];
 if (blocks.some(b=>b.includes(`${alias}.`))) { if (!routes.includes(imp)) routes=routes.replace('import (',`import (\n\t${imp}`); }
 else routes=routes.replace(new RegExp(`\\s*${alias} "[^"\\n]+"`),'');
}
routes = routes.replace(/\n}\s*$/, `\n${blocks.join('\n\n')}\n}\n`);
writeFileSync(routeFile, routes);
for (const [kind, group] of ['handler', 'logic'].flatMap(kind => ['core', 'openapi/v1'].map(group => [kind, group]))) {
  const relative = `internal/${kind}/${group}/unsmeta`;
  const target = join(backend, relative);
  mkdirSync(target, { recursive: true });
  if (!existsSync(join(temp, relative))) continue;
  for (const file of readdirSync(join(temp, relative))) {
    if (kind === 'handler' || !existsSync(join(target, file))) copyFileSync(join(temp, relative, file), join(target, file));
  }
  execFileSync('gofmt', ['-w', target]);
}
execFileSync('gofmt', ['-w', routeFile, typesFile]);
console.log(`Generated UNS metadata API: ${names.size} types, ${Object.keys(generatedSwagger.paths).length} paths.`);

